solid.fragmentPars:
uniform highp sampler2D lookSettings;

flat varying float vLookId;
varying vec3 vLookInfo;
varying vec2 vLookUv;
varying vec3 vLookWorld;
varying vec3 vLookWN;
varying vec3 vS0;
varying vec3 vS1;
varying vec4 vS2;
varying vec2 vS3;
#define s0 vS0
#define s1 vS1
#define s2 vS2
#define s3 vS3
uniform float lookView;
uniform float lookDebug;
// the looks' clock: seconds, one for every look of the scene, set each frame by the page (install.js's `time`) or the
// game (core's supershader3d). It grows without end, and a hash of a large number is no longer random, so a look never
// feeds it to its noise as it is: it takes it through kcycle or kloop, whose numbers stay inside one period.
uniform float lookTime;
// the uv's change across the pixel, worked out once where every pixel of the quad runs it, so a picture read inside a
// look's branch still knows its sharpness
vec2 lookGx, lookGy;
// the slot s3's change across the pixel, worked out beside them, for a picture laid by a place the geometry gives in s3
vec2 lookS3x, lookS3y;

float kh(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float kh1(float x) { return fract(sin(x * 91.7) * 43758.5453); }
float kn(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(kh(i), kh(i + vec2(1, 0)), u.x), mix(kh(i + vec2(0, 1)), kh(i + vec2(1, 1)), u.x), u.y);
}
float kfbm(vec2 p) {
  float a = 0.5, s = 0.0;
  for (int i = 0; i < 5; i++) { s += a * kn(p); p = p * 2.03 + 17.1; a *= 0.5; }
  return s / 0.97;
}
float kfbm4(vec2 p) {
  float a = 0.5, s = 0.0;
  for (int i = 0; i < 4; i++) { s += a * kn(p); p = p * 2.03 + 17.1; a *= 0.5; }
  return s;
}
// a feature f metres across fades to its mean where it is finer than a pixel
float kfade(float f) { vec2 fw = abs(lookGx) + abs(lookGy); return clamp(1.5 - (fw.x + fw.y) / f, 0.0, 1.0); }
// cells of jittered seeds: the distance to the nearest, its number (0 to 1), and how far the second is past it
float kvor(vec2 p, out float id, out float edge) {
  vec2 i = floor(p), f = fract(p);
  float d1 = 8.0, d2 = 8.0;
  vec2 best = vec2(0.0);
  for (int y = -1; y <= 1; y++) for (int x = -1; x <= 1; x++) {
    vec2 o = vec2(x, y);
    vec2 c = i + o;
    vec2 r = o + vec2(kh(c), kh(c + 7.3)) - f;
    float d = dot(r, r);
    if (d < d1) { d2 = d1; d1 = d; best = c; } else if (d < d2) { d2 = d; }
  }
  id = kh(best + 3.7);
  edge = sqrt(d2) - sqrt(d1);
  return sqrt(d1);
}
// a dimple field: the distance to the nearest of jittered cells' seeds
float kcell(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  float d = 8.0;
  for (int y = -1; y <= 1; y++) for (int x = -1; x <= 1; x++) {
    vec2 o = vec2(x, y);
    vec2 r = o + vec2(kh(i + o), kh(i + o + 7.3)) - f;
    d = min(d, dot(r, r));
  }
  return sqrt(d);
}
// courses: the row along v, the piece in it along u (each row offset), where in the piece (0 to 1 each way)
vec4 kcourse(vec2 uv, float row, float wide, float jitter, float seed, out vec2 id) {
  float r = floor(uv.y / row);
  float shift = kh1(r + seed) * wide;
  float w = wide * (1.0 - jitter * 0.5 + jitter * kh(vec2(r, floor((uv.x + shift) / wide) + seed)));
  float x = (uv.x + shift) / w;
  id = vec2(r, floor(x));
  return vec4(fract(x), fract(uv.y / row), r, w);
}
// marble's veins: thin lines wandering through a warped field, the main ones and finer ones across them
float kveins(vec2 p, float seed) {
  float w = kfbm(p * 1.3 + seed) * 4.0;
  float a = pow(1.0 - abs(sin((p.x * 1.6 + p.y * 0.6 + w) * 3.14159)), 22.0);
  float b = pow(1.0 - abs(sin((p.y * 2.7 - p.x * 1.1 + kfbm(p * 2.6 + seed + 7.0) * 3.0) * 3.14159)), 50.0);
  return clamp(a + 0.6 * b, 0.0, 1.0);
}
// wood's grain along u: its rings' lines (late wood 1, early 0) wandering across v, and its fibres
float kring(vec2 uv, float seed, float rings) {
  float w = kfbm(vec2(uv.x * 0.35, uv.y * 2.0) + seed) * 1.6;
  return smoothstep(0.5, 0.95, fract(uv.y * rings + w + uv.x * 0.04));
}
float kfibre(vec2 uv, float seed) { return kn(vec2(uv.x * 3.0, uv.y * 420.0) + seed) * kfade(0.003); }
// how strongly a cloth's weave shows: a plain weave of threads t metres across, over and under
float kweave(vec2 uv, float t) {
  vec2 q = uv / t;
  float warp = sin(q.x * 3.14159), weft = sin(q.y * 3.14159);
  float over = step(0.0, warp * weft);
  return mix(0.5, mix(0.8, 1.08, over) * (0.85 + 0.15 * abs(over > 0.5 ? weft : warp)), kfade(t * 2.0));
}
// a cycle of `period` seconds: how far through it the clock is, 0 to 1, for a look that pulses or goes round (anything
// of 6.28318 times it, a sin or a turn, comes back to where it began with no seam)
float kcycle(float period) { return fract(lookTime / period); }
// a drift that never repeats, for a look that flows, boils or creeps: two phases of one cycle of `period` seconds, half
// a cycle apart, each 0 to 1 (x and y), and the share of the first (z). A look moves its pattern on by each phase, reads
// it at both and mixes them by z; each phase jumps back to 0 only where its share is 0, so the drift shows no seam
vec3 kloop(float period) { float a = fract(lookTime / period); return vec3(a, fract(a + 0.5), 1.0 - abs(2.0 * a - 1.0)); }
// value noise in three numbers whose third repeats every `n` cells (a whole number): a pattern that churns in place,
// for what boils, breathes or glows and fades, never sliding as a drift does. Given p.z = kcycle(period) * n it changes
// n cells' worth over the period and comes back to where it began at its end with no seam, so nothing is mixed and
// nothing shows twice
float kh3(vec3 c) { return fract(sin(dot(c, vec3(127.1, 311.7, 74.7))) * 43758.5453123); }
float kn3(vec3 p, float n) {
  vec3 i = floor(p), f = fract(p);
  vec3 u = f * f * (3.0 - 2.0 * f);
  float z0 = mod(i.z, n), z1 = mod(i.z + 1.0, n);
  float a0 = mix(mix(kh3(vec3(i.xy, z0)), kh3(vec3(i.xy + vec2(1, 0), z0)), u.x),
                 mix(kh3(vec3(i.xy + vec2(0, 1), z0)), kh3(vec3(i.xy + vec2(1, 1), z0)), u.x), u.y);
  float a1 = mix(mix(kh3(vec3(i.xy, z1)), kh3(vec3(i.xy + vec2(1, 0), z1)), u.x),
                 mix(kh3(vec3(i.xy + vec2(0, 1), z1)), kh3(vec3(i.xy + vec2(1, 1), z1)), u.x), u.y);
  return mix(a0, a1, u.z);
}
// four sizes of it, each finer one churning twice as fast and still repeating on the same cycle
float kfbm3(vec3 p, float n) {
  float a = 0.5, s = 0.0;
  for (int i = 0; i < 4; i++) { s += a * kn3(p, n); p = vec3(p.xy * 2.03 + 17.1, p.z * 2.0); n *= 2.0; a *= 0.5; }
  return s / 0.9375;
}
// the normal bent by a height field, as three's bump map bends it (perturbNormalArb)
vec3 kitBump(vec3 pos, vec3 n, float h, float faceDirection) {
  vec3 sx = dFdx(pos), sy = dFdy(pos);
  vec3 r1 = cross(sy, n), r2 = cross(n, sx);
  float det = dot(sx, r1) * faceDirection;
  vec2 dh = vec2(dFdx(h), dFdy(h));
  vec3 grad = sign(det) * (dh.x * r1 + dh.y * r2);
  return normalize(abs(det) * n - grad);
}
// a normal in the surface's own ways (u, v, out) turned into the view's, the ways found from the uv's change across
// the pixel, as three's normal map without tangents finds them (getTangentFrame)
vec3 lookPerturb(vec3 n, vec3 nts, float faceDirection) {
  vec3 q0 = dFdx(-vViewPosition), q1 = dFdy(-vViewPosition);
  vec3 q1perp = cross(q1, n), q0perp = cross(n, q0);
  vec3 T = q1perp * lookGx.x + q0perp * lookGy.x;
  vec3 B = q1perp * lookGx.y + q0perp * lookGy.y;
  float det = max(dot(T, T), dot(B, B));
  float scale = det == 0.0 ? 0.0 : faceDirection * inversesqrt(det);
  return normalize(T * (nts.x * scale) + B * (nts.y * scale) + n * nts.z);
}

struct Look {
  vec3 colour; float rough; float metal; float height; vec3 nts; vec3 normal; bool ownNormal;
  float ao; float aoDirect; float alpha; vec3 glow;
  float clearcoat; float clearcoatRough; vec3 sheen; float sheenRough; float iridescence; float iridIor; float iridThick;
  float transmission; float thickness; vec3 attColour; float attDist; float ior; float dispersion;
};
Look lookStart() {
  Look k;
  k.colour = vec3(0.5); k.rough = 0.8; k.metal = 0.0; k.height = 0.0; k.nts = vec3(0.0, 0.0, 1.0);
  k.normal = vec3(0.0, 0.0, 1.0); k.ownNormal = false; k.ao = 1.0; k.aoDirect = 0.0; k.alpha = 1.0; k.glow = vec3(0.0);
  k.clearcoat = 0.0; k.clearcoatRough = 0.1; k.sheen = vec3(0.0); k.sheenRough = 0.5;
  k.iridescence = 0.0; k.iridIor = 1.3; k.iridThick = 400.0;
  k.transmission = 0.0; k.thickness = 0.0; k.attColour = vec3(1.0); k.attDist = 1e9; k.ior = 1.5; k.dispersion = 0.0;
  return k;
}


vec3 p_gsColour;
vec3 p_gsTint;
float p_gsTintShare;
float p_gsMetal;
float p_gsRough;
float p_gsMachine;
float p_gsMachinePitch;
float p_gsGrain;
float p_gsGrainSize;
float p_gsWear;
float p_gsWearBend;
vec3 p_gsWearColour;
float p_gsWearRough;
float p_gsWearMetal;
float p_gsOil;
float p_gsOilRough;
vec3 p_gpColour;
vec3 p_gpColour2;
float p_gpRough;
float p_gpStipple;
float p_gpStippleSize;
float p_gpChecker;
float p_gpCheckerAll;
float p_gpCheckerPitch;
float p_gpCheckerAngle;
float p_gpCheckerDepth;
float p_gpSwirl;
float p_gpWear;
float p_gpWearBend;
float p_gpSheen;
vec3 p_ctColour;
float p_ctMetal;
float p_ctRough;
float p_ctLines;
float p_ctTarnish;
vec3 p_ctTarnishColour;
float p_ctLacquer;
float p_ctSoot;



float ckLines(vec2 uv, float pitch, float angle, out float ckGroove) {
  float a = radians(angle);
  vec2 d1 = vec2(cos(a), sin(a)), d2 = vec2(cos(a), -sin(a));
  // each set of grooves runs along its direction; a point's place across them is its distance along the normal
  float q1 = dot(uv, vec2(-d1.y, d1.x)) / pitch;
  float q2 = dot(uv, vec2(-d2.y, d2.x)) / pitch;
  float t1 = abs(fract(q1) - 0.5) * 2.0;
  float t2 = abs(fract(q2) - 0.5) * 2.0;
  // a diamond's height falls from its point to each groove: the lesser of its distances to the two nearest grooves
  float h = min(t1, t2);
  ckGroove = 1.0 - smoothstep(0.0, 0.35, h);
  return h;
}
float ckHeight(vec2 uv, float pitch, float angle, out float ckGroove) {
  float f = kfade(pitch * 3.0);
  float g;
  float h = ckLines(uv, pitch, angle, g);
  ckGroove = g * f;
  return mix(0.5, h, f);
}




void look_0(inout Look k, int lookRow) {
  p_gsColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_gsTint = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_gsTintShare = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_gsMetal = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_gsRough = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_gsMachine = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_gsMachinePitch = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_gsGrain = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_gsGrainSize = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_gsWear = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  p_gsWearBend = texelFetch(lookSettings, ivec2(10, lookRow), 0).r;
  p_gsWearColour = texelFetch(lookSettings, ivec2(11, lookRow), 0).rgb;
  p_gsWearRough = texelFetch(lookSettings, ivec2(12, lookRow), 0).r;
  p_gsWearMetal = texelFetch(lookSettings, ivec2(13, lookRow), 0).r;
  p_gsOil = texelFetch(lookSettings, ivec2(14, lookRow), 0).r;
  p_gsOilRough = texelFetch(lookSettings, ivec2(15, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // machining: lines along u, fading to their mean where a pitch is under a pixel
    float gsMf = kfade(p_gsMachinePitch * 3.0);
    float gsLine = kn(vec2(uv.x * 40.0, uv.y / p_gsMachinePitch) + seed) * gsMf;
    // grain: two sizes of cells, a speckle of crystals
    float gsGf = kfade(p_gsGrainSize * 2.0);
    float gsCell = kcell(uv / p_gsGrainSize + seed * 7.0);
    float gsFleck = (kh(floor(uv / p_gsGrainSize) + seed) - 0.5) * gsGf;
    float gsG = p_gsGrain * gsGf;
    // wear: where the surface bends sharply, in patches
    float gsBend = length(fwidth(wn)) / max(length(fwidth(wp)), 1e-6);
    float gsEdge = smoothstep(p_gsWearBend * 0.35, p_gsWearBend, gsBend);
    float gsPatch = smoothstep(0.35, 0.75, kfbm(uv * 180.0 + seed * 3.1) * 0.7 + kn(uv * 900.0 + seed) * 0.3);
    float gsW = clamp(p_gsWear * gsEdge * (0.25 + 0.75 * gsPatch), 0.0, 1.0);
    // the finish's colour, a touch of its tint in the highlight, the flecks lighter and darker
    float gsTone = 0.92 + 0.12 * kfbm4(uv * 30.0 + seed) + 0.25 * gsG * gsFleck;
    vec3 gsC = mix(p_gsColour, p_gsTint, p_gsTintShare * (0.5 + 0.5 * gsLine)) * gsTone;
    k.colour = mix(gsC, p_gsWearColour * (0.9 + 0.1 * gsLine), gsW);
    k.metal = mix(p_gsMetal, p_gsWearMetal, gsW);
    k.rough = clamp(mix(p_gsRough + 0.08 * p_gsMachine * (gsLine - 0.5) + 0.15 * gsG * (gsCell - 0.5),
                        p_gsWearRough + 0.06 * gsLine, gsW), 0.02, 1.0);
    k.height = 0.000004 * p_gsMachine * gsLine + 0.00001 * gsG * (1.0 - gsCell);
    k.clearcoat = p_gsOil * (1.0 - 0.6 * gsW);
    k.clearcoatRough = p_gsOilRough;

}

void look_1(inout Look k, int lookRow) {
  p_gpColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_gpColour2 = texelFetch(lookSettings, ivec2(1, lookRow), 0).rgb;
  p_gpRough = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_gpStipple = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_gpStippleSize = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_gpChecker = texelFetch(lookSettings, ivec2(5, lookRow), 0).r;
  p_gpCheckerAll = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_gpCheckerPitch = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  p_gpCheckerAngle = texelFetch(lookSettings, ivec2(8, lookRow), 0).r;
  p_gpCheckerDepth = texelFetch(lookSettings, ivec2(9, lookRow), 0).r;
  p_gpSwirl = texelFetch(lookSettings, ivec2(10, lookRow), 0).r;
  p_gpWear = texelFetch(lookSettings, ivec2(11, lookRow), 0).r;
  p_gpWearBend = texelFetch(lookSettings, ivec2(12, lookRow), 0).r;
  p_gpSheen = texelFetch(lookSettings, ivec2(13, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the stipple: cells, each a small bump, fading to its mean
    float gpSf = kfade(p_gpStippleSize * 2.0);
    float gpCell = (1.0 - kcell(uv / p_gpStippleSize + seed * 5.0)) * gpSf;
    float gpSt = p_gpStipple * gpCell;
    // the swirl: streaks drawn out along u
    float gpSw = p_gpSwirl * kfbm(vec2(uv.x * 40.0, uv.y * 140.0) + seed);
    vec3 gpC = mix(p_gpColour, p_gpColour2, clamp(gpSw * 1.6 + 0.15 * kfbm4(uv * 60.0 + seed), 0.0, 1.0));
    // checkering where the kind says, or everywhere
    float gpOn = clamp(max(step(0.5, s3.x), p_gpCheckerAll) * p_gpChecker, 0.0, 1.0);
    float gpGroove;
    float gpCh = ckHeight(uv, p_gpCheckerPitch, p_gpCheckerAngle, gpGroove);
    // wear on its edges: glossier and paler
    float gpBend = length(fwidth(wn)) / max(length(fwidth(wp)), 1e-6);
    float gpEdge = p_gpWear * smoothstep(p_gpWearBend * 0.35, p_gpWearBend, gpBend);
    // the checkers' points rub glossy too
    float gpRub = max(gpEdge, gpOn * 0.5 * smoothstep(0.7, 1.0, gpCh));
    k.colour = gpC * (1.0 - 0.35 * gpOn * gpGroove) * (1.0 + 0.25 * gpRub) * (0.97 + 0.06 * gpSt);
    k.rough = clamp(p_gpRough + 0.12 * gpSt - 0.3 * gpRub, 0.05, 1.0);
    k.metal = 0.0;
    k.height = 0.00003 * gpSt + gpOn * p_gpCheckerDepth * gpCh;
    k.clearcoat = p_gpSheen;
    k.clearcoatRough = 0.4;

}

void look_2(inout Look k, int lookRow) {
  p_ctColour = texelFetch(lookSettings, ivec2(0, lookRow), 0).rgb;
  p_ctMetal = texelFetch(lookSettings, ivec2(1, lookRow), 0).r;
  p_ctRough = texelFetch(lookSettings, ivec2(2, lookRow), 0).r;
  p_ctLines = texelFetch(lookSettings, ivec2(3, lookRow), 0).r;
  p_ctTarnish = texelFetch(lookSettings, ivec2(4, lookRow), 0).r;
  p_ctTarnishColour = texelFetch(lookSettings, ivec2(5, lookRow), 0).rgb;
  p_ctLacquer = texelFetch(lookSettings, ivec2(6, lookRow), 0).r;
  p_ctSoot = texelFetch(lookSettings, ivec2(7, lookRow), 0).r;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float ctLf = kfade(0.00005);
    float ctL = kn(vec2(uv.x * 30000.0, uv.y * 30.0) + seed) * ctLf;
    float ctT = p_ctTarnish * smoothstep(0.45, 0.85, kfbm(uv * 400.0 + seed));
    vec3 ctC = p_ctColour * (0.94 + 0.12 * ctL * p_ctLines) * (0.96 + 0.08 * kfbm4(uv * 200.0 + seed));
    ctC = mix(ctC, p_ctTarnishColour, ctT);
    float ctS = p_ctSoot * smoothstep(0.3, 1.0, kfbm(uv * 600.0 + seed * 2.0));
    ctC = mix(ctC, vec3(0.03, 0.028, 0.026), ctS);
    k.colour = ctC;
    k.metal = mix(p_ctMetal, 0.2, max(ctS, 0.7 * p_ctLacquer));
    k.rough = clamp(p_ctRough + 0.08 * ctL * p_ctLines + 0.3 * ctT + 0.5 * ctS, 0.03, 1.0);
    k.clearcoat = p_ctLacquer;
    k.clearcoatRough = 0.25;

}


















Look lookRun(int id) {
  Look k = lookStart();
  switch (id) {
    case 0: look_0(k, 0); break;
    case 1: look_1(k, 1); break;
    case 2: look_2(k, 2); break;
    case 3: look_2(k, 3); break;
    case 4: look_2(k, 4); break;
    case 5: look_0(k, 5); break;
    case 6: look_0(k, 6); break;
    case 7: look_0(k, 7); break;
    case 8: look_1(k, 8); break;
    case 9: look_2(k, 9); break;
  }
  if (lookDebug > 0.5) {
    switch (id) {
      case 0: k.colour = vec3(0.024157632448504756, 0.026241221894849898, 0.0295568344378088); break;
      case 1: k.colour = vec3(0.007499032043226175, 0.007499032043226175, 0.008023192985384994); break;
      case 2: k.colour = vec3(0.5840784178911641, 0.3564001441459435, 0.06847816984440017); break;
      case 3: k.colour = vec3(0.4793201831008268, 0.14412847085805777, 0.04518620438567554); break;
